  function skillRow(skill) {
    const row2 = document.createElement("div");
    row2.className = "settings-row rule-row";
    const copy2 = document.createElement("button");
    copy2.type = "button";
    copy2.className = "settings-copy rule-open";
    const name = document.createElement("div");
    name.className = "settings-label";
    name.textContent = skill.name;
    const hint = document.createElement("div");
    hint.className = "settings-hint";
    const scope = tr(
      skill.scope === "project" ? "settingsSkillsProject" : skill.scope === "bundled" ? "settingsSkillsBundled" : "settingsSkillsGlobal"
    );
    hint.textContent = skill.description ? `${scope} \xB7 ${skill.description}` : scope;
    copy2.append(name, hint);
    copy2.addEventListener("click", () => post({ type: "openSkill", id: skill.id }));
    const tools = document.createElement("div");
    tools.className = "rule-tools";
    const toggle2 = document.createElement("button");
    toggle2.type = "button";
    toggle2.className = skill.enabled ? "switch on" : "switch";
    toggle2.setAttribute("role", "switch");
    toggle2.setAttribute("aria-checked", skill.enabled ? "true" : "false");
    toggle2.title = skill.enabled ? tr("settingsSkillsOn") : tr("settingsSkillsOff");
    const knob = document.createElement("span");
    knob.className = "knob";
    toggle2.append(knob);
    toggle2.addEventListener("click", (event) => {
      event.stopPropagation();
      if (skill.scope === "bundled") {
        return;
      }
      post({ type: "toggleSkill", id: skill.id });
    });
    if (skill.scope !== "bundled") {
      const del = document.createElement("button");
      del.type = "button";
      del.className = "btn";
      del.textContent = tr("settingsSkillsDelete");
      del.addEventListener("click", (event) => {
        event.stopPropagation();
        post({ type: "deleteSkill", id: skill.id });
      });
      tools.append(toggle2, del);
    } else {
      toggle2.disabled = true;
      tools.append(toggle2);
    }
    row2.append(copy2, tools);
    return row2;
  }

