  function syncQuota(root2) {
    const wrap = root2.querySelector('[data-quota="wrap"]');
    if (!wrap) {
      return;
    }
    const official = isOfficialGrokAccount(ui.state.account);
    const quota = ui.state.billing;
    const loading = Boolean(ui.state.billingLoading) && !quota;
    if (!official || !quota && !ui.state.billingLoading) {
      wrap.hidden = true;
      return;
    }
    wrap.hidden = false;
    const locale = ui.state.locale === "zh-CN" ? "zh-CN" : "en";
    const loadingEl = wrap.querySelector('[data-quota="loading"]');
    const title = wrap.querySelector('[data-quota="title"]');
    const used = wrap.querySelector('[data-quota="used"]');
    const reset = wrap.querySelector('[data-quota="reset"]');
    const bar = wrap.querySelector('[data-quota="bar"]');
    const fill = wrap.querySelector('[data-quota="fill"]');
    const product = wrap.querySelector('[data-quota="product"]');
    const productName = wrap.querySelector('[data-quota="product-name"]');
    const productPct = wrap.querySelector('[data-quota="product-pct"]');
    if (loadingEl) {
      loadingEl.textContent = tr("quotaLoading");
      loadingEl.hidden = !loading;
    }
    if (!quota) {
      if (title) {
        title.hidden = true;
      }
      if (used) {
        used.hidden = true;
      }
      if (reset) {
        reset.hidden = true;
      }
      if (bar) {
        bar.hidden = true;
      }
      if (product) {
        product.hidden = true;
      }
      return;
    }
    const percent = displayUsagePercent(quota.usagePercent);
    if (title) {
      title.hidden = false;
      title.textContent = quotaTitle(locale, quota);
    }
    if (used) {
      used.hidden = false;
      used.textContent = tr("quotaUsed", { n: percent });
    }
    const resetText = formatQuotaReset(locale, quota.periodEnd);
    if (reset) {
      reset.hidden = !resetText;
      reset.textContent = resetText ? tr("quotaReset", { time: resetText }) : "";
    }
    if (bar) {
      bar.hidden = false;
      bar.classList.toggle("warn", percent >= 80 && percent < 100);
      bar.classList.toggle("hot", percent >= 100);
    }
    if (fill) {
      fill.style.width = `${percent}%`;
    }
    const row2 = quota.products[0];
    if (product) {
      product.hidden = !row2;
    }
    if (row2 && productName && productPct) {
      productName.textContent = row2.label;
      productPct.textContent = `${displayUsagePercent(row2.usagePercent)}%`;
    }
  }
